script:
(function () {
  'use strict';
  // Annual stock option grants: one grant at the start of each year, each struck at the share price
  // on its grant date (at the money), vesting on its anniversaries, valued at intrinsic value.
  //   Price path: P0 = today's price; year-end price t = custom price t if entered, otherwise
  //   P(t-1) x (1 + growth). Grant k (k = 1..G) is made at time k-1 with strike K_k = P(k-1) and
  //   N_k = N1 x (1 + grant growth)^(k-1) options (rounded to whole options).
  //   At year end t a grant aged a = t - (k-1) years is vested: graded V years -> min(1, a / V);
  //   cliff C years -> 1 once a >= C, else 0. Value = options x max(0, P_t - K_k) (pre-tax spread).
  //   A grant whose option term ends (a >= term) is assumed exercised on its expiry date if it is
  //   in the money: gain = N_k x max(0, P(k-1+term) - K_k); out-of-the-money options lapse.
  // Verified (scratchpad b7opt/tests/sg.test.js), by hand: $50 today, 10% growth, 500 options a
  //   year, 25% a year over 4 years: year 2 -> price $60.50; grant 1 half vested: 250 x $10.50 =
  //   $2,625 vested + $2,625 unvested; grant 2 (strike $55) 25% vested: 125 x $5.50 = $687.50
  //   vested + $2,062.50 unvested; year 4 grant 1 fully vested 500 x ($73.21 - $50) = $11,602.50;
  //   with a 3-year option term, grant 1 is exercised at year 3 for 500 x ($66.55 - $50) = $8,275;
  //   falling prices leave grants underwater at $0 (never negative).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var whole = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var VESTING = { g4: { years: 4, cliff: false }, g3: { years: 3, cliff: false }, g5: { years: 5, cliff: false }, c3: { years: 3, cliff: true }, c4: { years: 4, cliff: true } };

  function raw(id) { return document.getElementById(id).value.trim(); }
  function num(id) { var v = parseFloat(raw(id)); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function vestedFraction(age, vest) {
    if (vest.cliff) return age >= vest.years ? 1 : 0;
    return Math.min(1, Math.floor(age + 1e-9) / vest.years);
  }

  // prices[t] for t = 0..H (t = 0 is today).
  function pricePath(p0, growth, custom, H) {
    var prices = [p0];
    for (var t = 1; t <= H; t++) prices.push(t - 1 < custom.length ? custom[t - 1] : prices[t - 1] * (1 + growth));
    return prices;
  }

  function simulate(o) {
    var H = Math.max(o.years, o.grantYears + o.term);
    var prices = pricePath(o.price, o.growth, o.custom, H);
    var grants = [];
    for (var k = 1; k <= o.grantYears; k++) {
      grants.push({ k: k, n: Math.round(o.grant * Math.pow(1 + o.grantGrowth, k - 1)), strike: prices[k - 1] });
    }
    var rows = [];
    for (var t = 1; t <= o.years; t++) {
      var r = { year: t, price: prices[t], granted: 0, vested: 0, unvested: 0, vestedValue: 0, unvestedValue: 0, exercised: 0 };
      grants.forEach(function (g) {
        if (g.k > t) return;
        r.granted += g.n;
        var age = t - (g.k - 1);
        if (age >= o.term) { r.exercised += g.n * Math.max(0, prices[g.k - 1 + o.term] - g.strike); return; }
        var v = vestedFraction(age, o.vest), spread = Math.max(0, prices[t] - g.strike);
        var nv = Math.round(g.n * v);
        r.vested += nv; r.unvested += g.n - nv;
        r.vestedValue += nv * spread; r.unvestedValue += (g.n - nv) * spread;
      });
      rows.push(r);
    }
    return { prices: prices, grants: grants, rows: rows };
  }

  function parseCustom(text) {
    if (!text) return [];
    var parts = text.split(/[;\s]+|,\s+/).filter(function (s) { return s !== ''; });
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var v = parseFloat(parts[i].replace(/^\$/, ''));
      if (isNaN(v) || v < 0 || !/^\$?\d*\.?\d+$/.test(parts[i])) return null;
      out.push(v);
    }
    return out;
  }

  var RESULT_IDS = ['sgTotal', 'sgVested', 'sgUnvested', 'sgExercised', 'sgCount', 'sgAvgStrike'];
  function clearResults() {
    RESULT_IDS.forEach(function (id) { set(id, '–'); set(id + 'Note', ''); });
    clearBody('sgYearTable'); clearBody('sgGrantTable');
  }

  function update() {
    var error = document.getElementById('sgError');
    var price = num('sgPrice'), grant = num('sgGrant'), grantYears = num('sgGrantYears'), growth = num('sgGrowth'),
        years = num('sgYears'), grantGrowth = raw('sgGrantGrowth') === '' ? 0 : num('sgGrantGrowth'),
        term = raw('sgTerm') === '' ? 10 : num('sgTerm');
    var custom = parseCustom(raw('sgPath'));
    var vest = VESTING[document.getElementById('sgVest').value] || VESTING.g4;
    var problem = '';
    if (isNaN(price) || price <= 0) problem = 'Enter a share price above $0.';
    else if (isNaN(grant) || grant < 1 || grant > 1e8) problem = 'Enter at least 1 option per yearly grant.';
    else if (isNaN(grantYears) || grantYears < 1 || grantYears > 40 || Math.round(grantYears) !== grantYears) problem = 'Enter 1 to 40 yearly grants (whole years).';
    else if (isNaN(growth) || growth < -90 || growth > 100) problem = 'Enter a share price growth rate from −90% to 100% a year.';
    else if (isNaN(years) || years < 1 || years > 50 || Math.round(years) !== years) problem = 'Enter 1 to 50 years to show (whole years).';
    else if (isNaN(grantGrowth) || grantGrowth < -50 || grantGrowth > 25) problem = 'Enter a change in grant size from −50% to 25% a year.';
    else if (isNaN(term) || term < 1 || term > 15 || Math.round(term) !== term) problem = 'Enter an option term of 1 to 15 whole years.';
    else if (custom === null) problem = 'Custom prices must be numbers of 0 or more, separated by a comma and a space or by new lines, with no thousands separators.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var sim = simulate({ price: price, grant: grant, grantYears: grantYears, growth: growth / 100, years: years, grantGrowth: grantGrowth / 100, term: term, custom: custom, vest: vest });
    var last = sim.rows[sim.rows.length - 1];
    var made = sim.grants.filter(function (g) { return g.k <= years; });
    var count = made.reduce(function (s, g) { return s + g.n; }, 0);
    var avgStrike = made.reduce(function (s, g) { return s + g.n * g.strike; }, 0) / count;

    set('sgTotal', money0.format(last.vestedValue + last.unvestedValue + last.exercised));
    set('sgTotalNote', 'Pre-tax spread after ' + years + (years === 1 ? ' year' : ' years') + ', at a share price of ' + money.format(last.price) + '.');
    set('sgVested', money0.format(last.vestedValue));
    set('sgVestedNote', whole.format(last.vested) + ' vested options you could exercise.');
    set('sgUnvested', money0.format(last.unvestedValue));
    set('sgUnvestedNote', whole.format(last.unvested) + ' options still vesting — usually forfeited if you leave.');
    set('sgExercised', money0.format(last.exercised));
    set('sgExercisedNote', last.exercised > 0 ? 'Gains on grants that reached the end of their ' + term + '-year term.' : 'No grant has reached the end of its ' + term + '-year term yet.');
    set('sgCount', whole.format(count));
    set('sgCountNote', made.length + (made.length === 1 ? ' grant' : ' grants') + ' made in ' + years + (years === 1 ? ' year.' : ' years.'));
    set('sgAvgStrike', money.format(avgStrike));
    set('sgAvgStrikeNote', 'Weighted by the number of options in each grant.');

    var yt = clearBody('sgYearTable');
    sim.rows.forEach(function (r) {
      addRow(yt, [String(r.year), money.format(r.price), whole.format(r.granted), whole.format(r.vested), whole.format(r.unvested),
        money0.format(r.vestedValue), money0.format(r.unvestedValue), money0.format(r.exercised)]);
    });

    var gt = clearBody('sgGrantTable');
    made.forEach(function (g) {
      var age = years - (g.k - 1);
      var status, value, pctV;
      if (age >= term) {
        value = g.n * Math.max(0, sim.prices[g.k - 1 + term] - g.strike);
        status = value > 0 ? 'Exercised at expiry' : 'Expired underwater';
        pctV = '100%';
      } else {
        var v = vestedFraction(age, vest);
        value = g.n * Math.max(0, last.price - g.strike);
        status = v >= 1 ? 'Fully vested' : (v > 0 ? 'Vesting' : 'Not yet vested');
        if (last.price <= g.strike) status += ', underwater';
        pctV = Math.round(v * 100) + '%';
      }
      addRow(gt, ['Year ' + g.k, whole.format(g.n), money.format(g.strike), pctV, status, money0.format(value)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
